            background-color: var(--bg-panel);
            color: var(--text-primary);
            border: 1px solid var(--border-color);
        }

        .theme-original p {
            color: var(--text-primary);
        }

        .theme-day {
            background-color: #000000;
            color: #ffffff;
            border: 1px solid #333333;
        }

        .theme-day p {
            color: #ffffff;
        }

        .theme-night {
            background-color: #ffffff;
