<body>
    <!--
使用方法：
1. 为每个正文容器设置一个唯一的ID，例如 "narrative-block-UniqueId"。
2. 在onclick事件中，将这个唯一ID作为第一个参数传入switchTheme函数。
3. 默认主题通过在class中预设，例如 class="interactive-narrative-container theme-original"。
-->
    <div id="narrative-block-UniqueId" class="interactive-narrative-container theme-original">
        <div class="theme-switcher">
            <span
                class="theme-button btn-original"
                onclick="switchTheme('narrative-block-UniqueId', 'theme-original')"
            ></span>
            <span class="theme-button btn-day" onclick="switchTheme('narrative-block-UniqueId', 'theme-day')"></span>
            <span class="theme-button btn-night" onclick="switchTheme('narrative-block-UniqueId', 'theme-night')"></span>
        </div>
          <p>$1</p>
    </div>

    <script>
        function switchTheme(containerId, themeClass) {
            const container = document.getElementById(containerId);
            container.classList.remove('theme-original', 'theme-day', 'theme-night');
            container.classList.add(themeClass);
        }
    </script>
</body>
</html>
